const decimaldate={};decimaldate.DECIMALPLACES=6;decimaldate.RE_YEARMONTHDAY=/^(\-?\+?)(\d+)\-(\d\d)\-(\d\d)$/;decimaldate.iso2dec=isodate=>{const datepieces=isodate.match(decimaldate.RE_YEARMONTHDAY);if(!datepieces)throw new Error(`iso2dec() malformed date ${isodate}`);const[plusminus,yearstring,monthstring,daystring]=datepieces.slice(1);const monthint=parseInt(monthstring);const dayint=parseInt(daystring);let yearint=plusminus=="-"?-1*parseInt(yearstring):parseInt(yearstring);if(yearint<=0)yearint-=1;if(!decimaldate.isvalidmonthday(yearint,monthint,dayint))throw new Error(`iso2dec() invalid date ${isodate}`);const decbit=decimaldate.proportionofdayspassed(yearint,monthint,dayint);let decimaloutput;if(yearint<0){decimaloutput=1+1+yearint-(1-decbit)}else{decimaloutput=yearint+decbit}decimaloutput=parseFloat(decimaloutput.toFixed(decimaldate.DECIMALPLACES));return decimaloutput};decimaldate.dec2iso=decdate=>{const truedecdate=decdate-1;const ispositive=truedecdate>0;if(ispositive){yearint=Math.floor(truedecdate)+1}else{yearint=-Math.abs(Math.floor(truedecdate))}const dty=decimaldate.daysinyear(yearint);let targetday=dty*(Math.abs(truedecdate)%1);if(ispositive)targetday=Math.ceil(targetday);else targetday=dty-Math.floor(targetday);let monthint;let dayspassed=0;for(let m=1;m<=12;m++){monthint=m;const dtm=decimaldate.daysinmonth(yearint,monthint);if(dayspassed+dtm<targetday){dayspassed+=dtm}else{break}}const dayint=targetday-dayspassed;const monthstring=monthint.toString().padStart(2,"0");const daystring=dayint.toString().padStart(2,"0");let yearstring;if(yearint>0)yearstring=yearint.toString().padStart(4,"0");else if(yearint==-1)yearstring=Math.abs(yearint+1).toString().padStart(4,"0");else yearstring="-"+Math.abs(yearint+1).toString().padStart(4,"0");return`${yearstring}-${monthstring}-${daystring}`};decimaldate.isvalidmonthday=(yearint,monthint,dayint)=>{if(yearint!=parseInt(yearint)||yearint==0)return false;if(monthint!=parseInt(monthint))return false;if(dayint!=parseInt(dayint))return false;if(monthint<1||monthint>12)return false;if(dayint<1)return false;const dtm=decimaldate.daysinmonth(yearint,monthint);if(!dtm)return false;if(dayint>dtm)return false;return true};decimaldate.proportionofdayspassed=(yearint,monthint,dayint)=>{let dayspassed=0;for(let m=1;m<monthint;m++){const dtm=decimaldate.daysinmonth(yearint,m);dayspassed+=dtm}dayspassed=dayspassed+dayint-.5;const dty=decimaldate.daysinyear(yearint);return dayspassed/dty};decimaldate.daysinmonth=(yearint,monthint)=>{const monthdaycounts={1:31,2:28,3:31,4:30,5:31,6:30,7:31,8:31,9:30,10:31,11:30,12:31};if(decimaldate.isleapyear(yearint))monthdaycounts[2]=29;return monthdaycounts[monthint]};decimaldate.daysinyear=yearint=>{return decimaldate.isleapyear(yearint)?366:365};decimaldate.isleapyear=yearint=>{if(yearint!=parseInt(yearint)||yearint==0)throw new Error(`isleapyear() invalid year ${yearint}`);const yearnumber=yearint>0?yearint:yearint+1;const isleap=yearnumber%4==0&&(yearnumber%100!=0||yearnumber%400==0);return isleap};